(ns cfapp.api.domain.movement.gymnastic
  (:require
   [cfapp.api.domain.movement.common :as common]
   [cfapp.api.domain.movement.element
    :refer
    [air-bike
     assault-bike
     ball-slam
     banded
     bar
     bar-facing
     battling-ropes
     box
     box-jump
     burpee
     chest-to
     chin-up
     cluster
     crunch
     deficit
     devil-press
     dip
     double-hand
     double-kettlebell-walk
     double-under
     drag
     ghd-sit-up
     hand-release
     handstand
     hollow-rock
     hspu
     jumping
     jumping-jack
     kettlebell
     kipping
     knees
     knees-to-elbows
     leg-raise
     man-maker
     mountain-climber
     muscle-up
     over
     over-the-bar
     parallette
     peg-board
     plank
     pull-as-adjective
     pull-up
     push
     push-up
     resting
     ring
     rope-climb
     row
     run
     sandbag-carry
     shuttle-sprint
     single
     single-under
     sit-up
     skierg
     sled
     step-over
     step-up
     strict
     swim
     toes-to
     toes-to-bar
     triple-under
     turkish-get-up
     v-up
     walk
     wall-ball
     wall-climb
     yoke-carry]]
   [cfapp.api.domain.movement.util :refer [combine elem multiply plus]]))

(def burpees
  (plus
    burpee
    (multiply
      #{nil bar-facing}
      burpee
      #{over-the-bar})))

(def pulls
  (let [raw-toes-to-something
        (plus
          toes-to-bar
          (multiply
            toes-to
            ring)
          (multiply
            #{chest-to}
            #{bar ring}))]
    (plus
      (multiply
        #{nil kipping strict jumping burpee}
        #{nil bar ring}
        #{pull-up muscle-up})
      (multiply
        #{nil kipping strict jumping burpee}
        (plus
          raw-toes-to-something
          (multiply
            #{toes-to chest-to}
            #{ring})))
      #{chin-up knees-to-elbows})))

(def push-ups
  (multiply
    #{nil knees hand-release ring}
    push-up))

(def hspus
  (multiply
    #{nil kipping strict deficit parallette ring}
    hspu))


(def carries
  (plus
    #{sandbag-carry
      yoke-carry}
    (multiply
      common/all-one-hand-gear-configs-and-positions
      walk)
    ;; "double kettlebell walk" is generated by the **previous** line but we
    ;; _override_ it with this next one, which also matches "farmer walk".
    ;; This is a bit of a trick because this next one must declare the same id
    ;; as the one from the previous one to be sure to override it.
    double-kettlebell-walk))

(def abdominals
  #{sit-up
    v-up
    hollow-rock
    crunch
    leg-raise
    plank
    ghd-sit-up})

(def jumping-ropes
  #{single-under
    double-under
    triple-under})

(def calories
  #{air-bike
    assault-bike
    row
    run
    shuttle-sprint
    skierg})

(def compounds
  (multiply
    burpee
    #{nil bar ring}
    muscle-up))

(def devil-presses-man-makers
  (multiply
    (plus
      nil
      (multiply
        #{single double-hand}
        kettlebell))
    #{devil-press man-maker}))

(def sleds
  (multiply
    sled
    #{push pull-as-adjective drag}))

(def box-jumps
  (multiply
    #{nil burpee}
    box-jump
    #{nil over}))

(def step-ups
  (multiply
    #{nil burpee}
    (plus nil common/all-one-hand-gear-configs)
    box
    #{step-up step-over}))

(def rings
  (multiply
    #{nil banded strict}
    ring
    #{row dip}))

(def rope-climbs
  (multiply
    #{nil (elem "L E G SEP? L E S S")}
    rope-climb))

(def misc
  #{ball-slam
    battling-ropes
    cluster
    (combine handstand walk) ;; TODO ?? should I do this?
    jumping-jack
    mountain-climber
    peg-board
    resting
    swim
    turkish-get-up
    wall-ball
    wall-climb})

(def all
  (plus
    burpees
    rope-climbs
    pulls
    push-ups
    hspus
    carries
    abdominals
    devil-presses-man-makers
    jumping-ropes
    calories
    compounds
    sleds
    box-jumps
    step-ups
    rings
    misc))
